# region: intake
def intake(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: digest
def digest(xs, cut=5):
    lo = [v for v in xs if v < cut]
    hi = [v for v in xs if v >= cut]
    return {'n': len(xs), 'lo': len(lo), 'hi': len(hi)}

# region: shape
def shape(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n // bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return shape(digest(emit(fold(sift(intake(raw))))))

